// Renders TRANSITIONS as SQL rows for public.booking_transitions.
// Usage: pnpm --filter @hmj/booking gen:sql > ../../supabase/migrations/<file>.sql  (see test "sql is in sync")
import { STATES, TERMINAL_STATES, TRANSITIONS } from '../src/machine.ts';

export function renderSql(): string {
  const rows = TRANSITIONS.flatMap((x) => x.tracks.flatMap((track) => x.actors.map((actor) => `  ('${track}', '${x.from}', '${x.event}', '${x.to}', '${actor}')`)));
  return [
    '-- GENERATED by packages/booking/scripts/gen-sql.ts from packages/booking/src/machine.ts — do not edit.',
    '-- Regenerate: pnpm --filter @hmj/booking gen:sql > supabase/migrations/20260929000500_booking_machine.sql',
    '',
    `create type public.booking_state as enum (${STATES.map((s) => `'${s}'`).join(', ')});`,
    '',
    'create table public.booking_transitions (',
    '  track      public.job_track not null,',
    '  from_state public.booking_state not null,',
    '  event      text not null,',
    '  to_state   public.booking_state not null,',
    "  actor      text not null check (actor in ('junior', 'parent', 'employer', 'system')),",
    '  primary key (track, from_state, event, actor)',
    ');',
    '',
    'insert into public.booking_transitions (track, from_state, event, to_state, actor) values',
    rows.join(',\n') + ';',
    '',
    `create function public.booking_is_terminal(s public.booking_state) returns boolean language sql immutable as $$ select s in (${TERMINAL_STATES.map((s) => `'${s}'`).join(', ')}) $$;`,
    '',
    'alter table public.booking_transitions enable row level security;',
    'create policy "booking_transitions: readable" on public.booking_transitions for select to authenticated using (true);',
    'grant select on public.booking_transitions to authenticated;',
    '',
  ].join('\n');
}

if (import.meta.url === `file://${process.argv[1]}`) process.stdout.write(renderSql());
